def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(items, p):
        best = None
        best_d = None
        for it in items or []:
            q = pos(it)
            if q is None:
                continue
            d = dist(p, q)
            if best is None or d < best_d:
                best = q
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or self_pos
    sx, sy = self_pos
    ox, oy = opp_pos

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return clamp_move(sign(ox - sx), sign(oy - sy))
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        corners = [c for c in corners if c[0] >= 0 and c[1] >= 0]
        if corners:
            target = max(corners, key=lambda c: dist(c, opp_pos))
            return clamp_move(sign(target[0] - sx), sign(target[1] - sy))
        return clamp_move(-sign(ox - sx), -sign(oy - sy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("target_cells") or []
        target = nearest(targets, self_pos)
        if target is not None:
            return clamp_move(sign(target[0] - sx), sign(target[1] - sy))
        return clamp_move(sign(ox - sx), sign(oy - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("food") or []
    target = nearest(resources, self_pos)
    if target is not None:
        return clamp_move(sign(target[0] - sx), sign(target[1] - sy))

    threats = observation.get("opponents") or observation.get("enemy_positions") or []
    threat = nearest(threats, self_pos)
    if threat is not None:
        return clamp_move(-sign(threat[0] - sx), -sign(threat[1] - sy))

    return clamp_move(sign(ox - sx), sign(oy - sy))

